def _amt(rng, lo, hi, step=50):
    v = rng.randrange(lo, hi, step)
    return f"{v:,}" if rng.random() < 0.6 else str(v)


def _fill(slot, rng):
    if slot in SLOTS:
        return rng.choice(SLOTS[slot])
    if slot == "amt":
        return _amt(rng, 100, 20000)
    if slot == "big":
        return rng.choice([_amt(rng, 10000, 1000000, 500), f"{rng.randint(1, 10)} lakh", f"{rng.randint(1, 50)} hajar"])
    if slot == "fee":
        return _amt(rng, 20, 5000, 10)
    if slot == "small":
        return str(rng.choice([10, 20, 30, 45, 50, 60, 75, 99, 100, 120, 150, 200]))
    if slot == "code":
        return str(rng.randint(10 ** (k := rng.choice([4, 5, 6])) // 10, 10 ** k - 1))
    if slot == "hrs":
        return str(rng.choice([1, 2, 3, 6, 12, 24, 48]))
    if slot == "mins":
        return str(rng.choice([5, 10, 15, 30]))
    if slot == "pct":
        return str(rng.choice([5, 10, 15, 20, 25, 30, 40, 50, 60, 70]))
    if slot == "num":
        return str(rng.randint(2, 15))
    if slot == "phone":
        return rng.choice(["01XXXXXXXXX", "01XXXXXXXXX", "017XXXXXXXX", "018XXXXXXXX", "019XXXXXXXX", "+8801XXXXXXXXX",
                           "01X-XXXXXXXX", "015XXXXXXXX"])
    if slot == "bad":
        w = rng.sample(_BADW, 2)
        path = rng.choice(["", "/claim", "/login", "/verify", "/pay", "/track", "/app.apk", "/form", "/" + w[0]])
        if rng.random() < 0.12:
            return f"bit[.]ly/{''.join(rng.choice('abcdefghjkmnpqrstuvwxyz23456789') for _ in range(6))}"
        return f"{rng.choice(['hxxps', 'hxxp', 'hxxps', 'https'])}://{w[0]}-{w[1]}[.]{rng.choice(_TLD)}{path}"
    if slot == "ok":
        return "https://" + rng.choice(_OKDOM)
    if slot == "trx":
        return "".join(rng.choice("ABCDEFGHJKLMNPQRSTUVWXYZ0123456789") for _ in range(rng.choice([8, 10])))
    if slot == "ord":
        return rng.choice(["#", "", "#DZ", "#OR", "ID "]) + str(rng.randint(1000, 999999))
    if slot == "acc":
        return "XXXX" + str(rng.randint(1000, 9999))
    if slot == "date":
        return f"{rng.randint(1, 28)} {rng.choice(SLOTS['month'])}"
    if slot == "time":
        return rng.choice(["10 AM", "11:30 AM", "3 PM", "4:30 PM", "8 PM", "9 tay", "sokal 10 tay", "bikal 4 tay"])
    raise KeyError(slot)


# --------------------------------------------------------------------------------------------- claimed senders (T1)
SENDER = {
    "mfs": ["{mfs}:", "{mfs} Helpline:", "{mfs} Customer Care:", "Dear {mfs} user,", "{mfs} Support:", "{mfs} Agent:",
            "{mfs} Security Team:", "ami {mfs} office theke bolchi,", "{mfs} theke bolchi,", "{mfs_bn} হেল্পলাইন:"],
    "bank": ["{bank}:", "{bank} Card Division:", "Dear {bank} customer,", "{bank} Security:", "{bank} Customer Service:"],
    "tel": ["{tel}:", "{tel} Customer Care:", "Dear {tel} user,", "{tel} Offer:", "{tel_bn}:"],
    "shop": ["{shop}:", "{shop} Customer Care:", "{shop} refund team:", "{shop} Rewards:", "Dear {shop} customer,"],
    "courier": ["{courier}:", "{courier} notice:", "{courier} Customer Service:", "this is {courier},",
                "{courier_bn}:"],
    "emp": ["HR, {emp}:", "{emp} Recruitment:", "{emp} HR team:", "Recruiter from {emp}:"],
    "gov": ["{gov}:", "{gov} notice:", "Office of {gov}:"],
}


def _render(tpl, rng):
    """Fill {slot} and {S:kind}; return text and whether a sender was claimed."""
    claimed = False

    def rep(m):
        nonlocal claimed
        key = m.group(1)
        if key.startswith("S:"):
            claimed = True
            return _render(rng.choice(SENDER[key[2:]]), rng)[0]
        return _fill(key, rng)
    out = re.sub(r"\{([A-Za-z_:]+)\}", rep, tpl)
    return out, claimed


