# ------------------------------------------------------------------------------------------ registers / wrappers
_URG_EN = ["Act now!", "Offer valid for {hrs} hours only.", "Do it within {mins} minutes.", "Last warning.",
           "Otherwise your account will be closed.", "Hurry, limited time!", "Today is the last day."]
_URG_BL = ["Ekhoni korun.", "{hrs} ghontar moddhe korte hobe.", "Deri korle bondho hoye jabe.", "Shesh shujog!",
           "Ajker moddhe na korle cancel hobe."]
_URG_BN = ["এখনই করুন।", "অন্যথায় অ্যাকাউন্ট বন্ধ হয়ে যাবে।", "আজই শেষ সুযোগ!"]
_TRUST = {  # opening turns that build trust before the request
    "en": ["Hello, how are you?", "Assalamu alaikum.", "Hi, good evening.", "Hello sir, do you have a minute?",
           "Hi, I got your number from a friend."],
    "bl": ["Assalamu alaikum bhai, kemon achen?", "Hello apu, ektu kotha bolte parbo?", "Bhai ki obostha?",
           "Sir, apnar ektu shomoy hobe?"],
}
_REPLY = {"en": ["ok", "what is this?", "who are you?", "really?", "ok tell me", "how?", "I don't understand",
                 "is it safe?", "hmm", "what do I need to do?"],
          "bl": ["ji bolen", "ki bolen?", "apni ke?", "sotti?", "accha", "kivabe?", "bujhlam na", "thik ase",
                 "ki korte hobe?", "hmm"]}
_MARKERS = [("S:", "R:"), ("A:", "B:"), ("[Sender]", "[You]"), ("Caller:", "You:"), ("", "")]
_FILLER_EN = ["We value your trust.", "Thank you for staying with us.", "This is an automated message.",
              "For any query please contact customer support.", "Have a nice day."]


def _lang(text):
    if re.search(r"[ঀ-৿]", text):
        return "bn"
    return "bl" if re.search(r"\b(apnar|apni|korun|ami|taka|hobe|din|bhai|ache|ase|theke|jonno)\b", text, re.I) else "en"


def _split_sentences(text):
    parts = [p.strip() for p in re.split(r"(?<=[.!?।])\s+", text) if p.strip()]
    return parts if parts else [text]


def _as_conversation(text, rng, scam):
    lang = "bl" if _lang(text) != "en" else "en"
    m_s, m_r = rng.choice(_MARKERS)
    sents = _split_sentences(text)
    turns = []
    if scam and rng.random() < 0.7:
        turns.append((m_s, rng.choice(_TRUST[lang])))
        turns.append((m_r, rng.choice(_REPLY[lang])))
    for i, s in enumerate(sents):
        turns.append((m_s, s))
        if i < len(sents) - 1 or rng.random() < 0.4:
            turns.append((m_r, rng.choice(_REPLY[lang])))
    return " ||| ".join((f"{m} {t}" if m else t) for m, t in turns[:12])


def _as_group_chat(text, rng):
    who = rng.sample(SLOTS["name"], 2)
    pre = rng.choice(["Assalamu alaikum shobai", "Hi everyone", "Group er shobaike janacchi", "Important!"])
    return f"[Group] {who[0]}: {pre} ||| [Group] {who[0]}: {text} ||| [Group] {who[1]}: {rng.choice(['ok', 'interested', 'details den', 'kivabe?'])}"


def _as_email(text, rng, org):
    subj = rng.choice(["Important notice", "Account update", "Your request", "Notification", "Action required",
                       "Information"])
    return (f"Subject: {subj}. Dear Customer, {text} {rng.choice(_FILLER_EN)} Regards, {org or 'Customer Service'}")


def _as_call(text, rng):
    lang = "bl" if _lang(text) != "en" else "en"
    sents = _split_sentences(text)
    turns = ["Caller: " + rng.choice(_TRUST[lang])]
    for s in sents:
        turns += ["You: " + rng.choice(_REPLY[lang]), "Caller: " + s]
    return "Call transcript: " + " ||| ".join(turns)


def _warning_about(scam_text, rng):
    """Hard negative: someone quotes a scam to warn others (Class 0)."""
    q = scam_text if len(scam_text) < 160 else scam_text[:157] + "..."
    return rng.choice([
        f"Sabdhan! Ei message ta scam: '{q}' Keu reply diben na.",
        f"FYI got this fake SMS today: \"{q}\" Don't fall for it, report to 16216.",
        f"Bhai dekh ki scam message ashche: {q} -- eder theke dure thakis.",
        f"সতর্ক থাকুন! এই ধরনের প্রতারণামূলক মেসেজ আসছে: \"{q}\" কেউ সাড়া দেবেন না।",
        f"[Group] {rng.choice(SLOTS['name'])}: Ei message pele ignore korben, eta protarona: {q}",
    ])


def _techs_str(ts):
    order = ["T1", "T2", "T3", "T4", "T5", "T6"]
    s = [t for t in order if t in ts]
    return "|".join(s) if s else "NONE"


def generate(n=4000, seed=7, mix=None):
    """n labelled synthetic rows. mix = class weights (default leans legit, like a real inbox)."""
    rng = random.Random(seed)
    mix = mix or {0: 0.28, 1: 0.15, 2: 0.13, 3: 0.13, 4: 0.13, 5: 0.18}
    classes, weights = zip(*mix.items())
    out = []
    while len(out) < n:
        c = rng.choices(classes, weights)[0]
        if c in T:
            raw = rng.choice(T[c])
            techs, act, tpl = raw.split("|", 2)
            text, claimed = _render(tpl, rng)
            ts = set(t for t in techs.split(",") if t)
            if claimed:
                ts.add("T1")
            if "T5" not in ts and rng.random() < 0.2:          # add pressure -> T5
                lang = _lang(text)
                text += " " + _render(rng.choice(_URG_BN if lang == "bn" else _URG_BL if lang == "bl" else _URG_EN), rng)[0]
                ts.add("T5")
            r = rng.random()
            if r < 0.22:
                text = _as_conversation(text, rng, scam=True)
            elif r < 0.30:
                text = _as_call(text, rng)
            elif r < 0.36 and c == 3:
                text = _as_group_chat(text, rng)
            elif r < 0.42 and _lang(text) == "en":
                text = _as_email(text, rng, None)
            out.append((text, c, _techs_str(ts), int(act)))
            if rng.random() < 0.12:                             # paired hard negative: a warning quoting it
                out.append((_warning_about(text.replace(" ||| ", " "), rng), 0, "NONE", 0))
        else:
            text, _ = _render(rng.choice(LEGIT if c == 0 else PROMO), rng)
            r = rng.random()
            if r < 0.12 and "|||" not in text:
                text = _as_conversation(text, rng, scam=False)
            elif r < 0.18 and _lang(text) == "en" and "|||" not in text:
                text = _as_email(text, rng, None)
            out.append((text, c, "NONE", 0))
    df = pd.DataFrame(out[:n], columns=["text", "label", "techniques", "action"])
    if True:  # Bangla digits in half of the Bangla-script rows
        bn = df.text.str.contains(r"[ঀ-৿]") & (pd.Series([rng.random() for _ in range(len(df))]) < 0.5)
        df.loc[bn, "text"] = df.loc[bn, "text"].str.translate(_BN_DIGITS)
    return df.drop_duplicates("text").reset_index(drop=True)


if __name__ == "__main__":
    d = generate(3000)
    print(d.label.value_counts().sort_index().to_dict(), len(d))
    for c in range(6):
        print(c, d[d.label == c].sample(3, random_state=1).to_string(index=False, header=False)[:600])
